'use strict';
(function(){
  const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let channel=null,routeToken=0;
  const page=()=>document.querySelector('#page');
  const stop=()=>{routeToken++;if(channel){const active=channel;channel=null;try{void window.YamaPortalIntegration.sharedClient(location.origin).removeChannel(active);}catch{}}};
  const relativeTime=value=>{const date=new Date(value);return Number.isNaN(date.valueOf())?'':new Intl.DateTimeFormat('cs-CZ',{dateStyle:'short',timeStyle:'short'}).format(date);};
  const signedOut=kind=>`<section class="panel community-page"><a class="community-back" href="#domu">← Zpět na Domů</a><p class="eyebrow">YAMAPORTAL · ${kind==='chat'?'ŽIVÝ CHAT':'FÓRUM'}</p><h1>${kind==='chat'?'Živý chat':'Fórum Yamaportalu'}</h1><div class="notice"><strong>Přihlášení je potřeba</strong>Chat a fórum jsou dostupné pouze po přihlášení ke společnému účtu Yamaportalu.</div><a class="primary community-login" href="#profil">Přihlásit se →</a></section>`;
  const messageMarkup=rows=>rows.map(row=>`<article class="live-message"><div class="live-message-meta"><strong>${escape(row.profiles?.display_name||row.profiles?.username||'Uživatel Yamaportalu')}</strong><time datetime="${escape(row.created_at)}">${escape(relativeTime(row.created_at))}</time></div><p>${escape(row.body)}</p></article>`).join('');
  const topicMarkup=rows=>rows.map(row=>`<article class="forum-topic"><button type="button" class="forum-topic-open" data-topic-id="${escape(row.id)}"><span><strong>${escape(row.title)}</strong><span class="forum-topic-preview">${escape(row.body)}</span><span class="caption">${escape(row.profiles?.display_name||row.profiles?.username||'Uživatel Yamaportalu')} · ${escape(relativeTime(row.created_at))}</span></span><span class="forum-topic-cta">Otevřít diskusi →</span></button></article>`).join('');
  const replyMarkup=rows=>rows.map(row=>`<article class="forum-reply"><div class="live-message-meta"><strong>${escape(row.profiles?.display_name||row.profiles?.username||'Uživatel Yamaportalu')}</strong><time datetime="${escape(row.created_at)}">${escape(relativeTime(row.created_at))}</time></div><p>${escape(row.body)}</p></article>`).join('');
  async function show(route){
    stop();const token=routeToken,kind=route==='live-chat'?'chat':'forum';const target=page();if(!target)return;
    const shell=`<section class="panel community-page"><a class="community-back" href="#domu">← Zpět na Domů</a><p class="eyebrow">YAMAPORTAL · ${kind==='chat'?'ŽIVÝ CHAT':'FÓRUM'}</p><h1>${kind==='chat'?'Živý chat':'Fórum Yamaportalu'}</h1><p class="muted">${kind==='chat'?'Společná konverzace uživatelů Yamaportalu.':'Témata a nápady komunity Yamaportalu.'}</p><p class="form-status" data-community-status role="status">Ověřuji přihlášení…</p><div class="community-content" data-community-content></div></section>`;
    target.hidden=false;target.innerHTML=shell;
    let client,user,currentTopics=[];
    try{client=window.YamaPortalIntegration.sharedClient(location.origin);const result=await client.auth.getUser();user=result.data?.user;if(result.error)throw result.error;}
    catch(error){if(token!==routeToken)return;target.innerHTML=signedOut(kind);return;}
    if(token!==routeToken)return;
    if(!user){target.innerHTML=signedOut(kind);return;}
    const content=target.querySelector('[data-community-content]');const status=target.querySelector('[data-community-status]');
    try{
      if(kind==='chat'){
        content.innerHTML=`<div class="live-chat-list" aria-live="polite" data-live-messages><p class="muted">Načítám zprávy…</p></div><form class="community-form" id="portal-live-message"><label for="portal-live-message-body">Tvoje zpráva</label><div class="community-compose"><input id="portal-live-message-body" name="body" maxlength="1000" required autocomplete="off" placeholder="Napiš zprávu…"><button class="primary" type="submit">Odeslat</button></div></form>`;
        const result=await client.from('portal_chat_messages').select('id,user_id,body,created_at,profiles!portal_chat_messages_user_id_fkey(username,display_name)').order('created_at',{ascending:false}).limit(50);
        if(result.error)throw result.error;
        if(token!==routeToken)return;
        const list=content.querySelector('[data-live-messages]');list.innerHTML=messageMarkup((result.data||[]).slice().reverse())||'<p class="community-empty">Zatím tu nejsou žádné zprávy. Začni konverzaci.</p>';
        content.querySelector('#portal-live-message').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,input=form.elements.body,button=form.querySelector('button');const body=input.value.trim();if(!body||body.length>1000)return;button.disabled=true;status.textContent='Odesílám zprávu…';try{const saved=await client.from('portal_chat_messages').insert({user_id:user.id,body}).select('id').single();if(saved.error)throw saved.error;input.value='';status.textContent='Zpráva byla odeslána.';}catch(error){status.textContent=error.message||'Zprávu se nepodařilo odeslat.';}finally{button.disabled=false;input.focus();}});
        channel=client.channel('yamaportal-live-chat').on('postgres_changes',{event:'INSERT',schema:'public',table:'portal_chat_messages'},payload=>{if(token!==routeToken||!payload.new?.id)return;const list=content.querySelector('[data-live-messages]');if(!list||list.querySelector(`[data-message-id="${CSS.escape(payload.new.id)}"]`))return;void client.from('portal_chat_messages').select('id,user_id,body,created_at,profiles!portal_chat_messages_user_id_fkey(username,display_name)').eq('id',payload.new.id).maybeSingle().then(({data})=>{if(!data||token!==routeToken)return;const empty=list.querySelector('.community-empty');empty?.remove();const item=document.createElement('div');item.innerHTML=messageMarkup([data]);const node=item.firstElementChild;node.dataset.messageId=data.id;list.append(node);while(list.children.length>100)list.firstElementChild.remove();list.scrollTop=list.scrollHeight;});}).subscribe();
      }else{
        content.innerHTML=`<form class="community-form forum-create" id="portal-forum-topic"><h2>Založit téma</h2><label for="portal-forum-title">Název tématu</label><input id="portal-forum-title" name="title" maxlength="120" required><label for="portal-forum-body">Popis</label><textarea id="portal-forum-body" name="body" maxlength="5000" rows="4" required></textarea><button class="primary" type="submit">Založit téma</button></form><section class="forum-list" aria-live="polite" aria-label="Témata fóra"><h2>Aktuální témata</h2><div data-forum-topics><p class="muted">Načítám témata…</p></div></section>`;
        const result=await client.from('portal_forum_topics').select('id,user_id,title,body,created_at,profiles!portal_forum_topics_user_id_fkey(username,display_name)').order('created_at',{ascending:false}).limit(50);
        if(result.error)throw result.error;
        if(token!==routeToken)return;
        currentTopics=result.data||[];const list=content.querySelector('[data-forum-topics]');list.innerHTML=topicMarkup(currentTopics)||'<p class="community-empty">Fórum zatím nemá žádná témata.</p>';
        content.querySelector('#portal-forum-topic').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');const title=form.elements.title.value.trim(),body=form.elements.body.value.trim();if(!title||!body)return;button.disabled=true;status.textContent='Zakládám téma…';try{const saved=await client.from('portal_forum_topics').insert({user_id:user.id,title,body}).select('id').single();if(saved.error)throw saved.error;status.textContent='Téma bylo založeno.';form.reset();await refreshTopics();}catch(error){status.textContent=error.message||'Téma se nepodařilo založit.';}finally{button.disabled=false;}});
        let forumView=0;
        content.addEventListener('click',event=>{if(event.target.closest('[data-forum-back]')){forumView++;if(channel){const active=channel;channel=null;void client.removeChannel(active);}content.querySelector('[data-forum-detail]')?.remove();content.querySelector('.forum-create').hidden=false;content.querySelector('.forum-list').hidden=false;status.textContent='Připojeno k fóru.';void refreshTopics();return;}const button=event.target.closest('[data-topic-id]');if(!button)return;const topic=currentTopics.find(row=>row.id===button.dataset.topicId);if(topic)void openTopic(topic,++forumView);});
        async function openTopic(topic,view){if(channel){const active=channel;channel=null;void client.removeChannel(active);}const replyResult=await client.from('portal_forum_replies').select('id,user_id,topic_id,body,created_at,profiles!portal_forum_replies_user_id_fkey(username,display_name)').eq('topic_id',topic.id).order('created_at',{ascending:true}).limit(100);if(token!==routeToken||view!==forumView)return;if(replyResult.error){status.textContent='Diskusi se nepodařilo načíst.';return;}content.querySelector('.forum-create').hidden=true;content.querySelector('.forum-list').hidden=true;const detail=document.createElement('section');detail.className='forum-thread';detail.dataset.forumDetail='';detail.innerHTML=`<button type="button" class="secondary forum-back" data-forum-back>← Zpět na témata</button><article class="forum-thread-topic"><h2>${escape(topic.title)}</h2><p>${escape(topic.body)}</p><span class="caption">${escape(topic.profiles?.display_name||topic.profiles?.username||'Uživatel Yamaportalu')} · ${escape(relativeTime(topic.created_at))}</span></article><section class="forum-reply-list" aria-live="polite"><h3>Diskuze</h3><div data-forum-replies>${replyMarkup(replyResult.data||[])||'<p class="community-empty">Zatím tu není žádná odpověď. Začni diskuzi.</p>'}</div></section><form class="community-form forum-reply-form" data-forum-reply-form><label for="portal-forum-reply">Tvoje odpověď</label><textarea id="portal-forum-reply" name="body" maxlength="2000" rows="3" required placeholder="Napiš odpověď…"></textarea><button class="primary" type="submit">Odeslat odpověď</button></form>`;content.append(detail);detail.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),body=form.elements.body.value.trim();if(!body||body.length>2000)return;button.disabled=true;status.textContent='Odesílám odpověď…';try{const saved=await client.from('portal_forum_replies').insert({topic_id:topic.id,user_id:user.id,body}).select('id').single();if(saved.error)throw saved.error;form.reset();status.textContent='Odpověď byla přidána do diskuze.';await refreshReplies(topic,view);}catch(error){status.textContent=error.message||'Odpověď se nepodařilo odeslat.';}finally{button.disabled=false;}});channel=client.channel('yamaportal-forum-replies-'+topic.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'portal_forum_replies',filter:`topic_id=eq.${topic.id}`},payload=>{if(token!==routeToken||view!==forumView||!payload.new?.id)return;void client.from('portal_forum_replies').select('id,user_id,topic_id,body,created_at,profiles!portal_forum_replies_user_id_fkey(username,display_name)').eq('id',payload.new.id).maybeSingle().then(({data})=>{if(!data||token!==routeToken||view!==forumView)return;const replies=detail.querySelector('[data-forum-replies]');if(!replies||replies.querySelector(`[data-reply-id="${CSS.escape(data.id)}"]`))return;replies.querySelector('.community-empty')?.remove();const holder=document.createElement('div');holder.innerHTML=replyMarkup([data]);const item=holder.firstElementChild;item.dataset.replyId=data.id;replies.append(item);});}).subscribe();}
        async function refreshReplies(topic,view){const list=content.querySelector('[data-forum-replies]');if(!list)return;const {data,error}=await client.from('portal_forum_replies').select('id,user_id,topic_id,body,created_at,profiles!portal_forum_replies_user_id_fkey(username,display_name)').eq('topic_id',topic.id).order('created_at',{ascending:true}).limit(100);if(token!==routeToken||view!==forumView)return;if(error){status.textContent='Nepodařilo se obnovit diskuzi.';return;}list.innerHTML=replyMarkup(data||[])||'<p class="community-empty">Zatím tu není žádná odpověď. Začni diskuzi.</p>';}
        channel=client.channel('yamaportal-forum-topics').on('postgres_changes',{event:'INSERT',schema:'public',table:'portal_forum_topics'},payload=>{if(token!==routeToken||!payload.new?.id)return;void refreshTopics();}).subscribe();
      }
      status.textContent=kind==='chat'?'Připojeno ke společnému chatu.':'Připojeno k fóru.';
    }catch(error){if(token!==routeToken)return;status.textContent='Obsah se zatím nedá načíst. Zkontroluj připojení nebo dostupnost databáze.';content.innerHTML=`<p class="notice community-error"><strong>Funkce není připravená</strong>${escape(error.message||'Databázové tabulky Yamaportalu ještě nejsou nasazeny.')}</p><button type="button" class="secondary" data-community-retry>Opakovat</button>`;content.querySelector('[data-community-retry]').onclick=()=>show(route);}
    async function refreshTopics(){const list=content?.querySelector('[data-forum-topics]');if(!list)return;const {data,error}=await client.from('portal_forum_topics').select('id,user_id,title,body,created_at,profiles!portal_forum_topics_user_id_fkey(username,display_name)').order('created_at',{ascending:false}).limit(50);if(token!==routeToken)return;if(error){status.textContent='Nepodařilo se obnovit témata.';return;}currentTopics=data||[];list.innerHTML=topicMarkup(currentTopics)||'<p class="community-empty">Fórum zatím nemá žádná témata.</p>';}
  }
  window.YamaPortalCommunity=Object.freeze({show,stop});
  window.addEventListener('hashchange',()=>{if(!['#live-chat','#forum'].includes(location.hash))stop();});
  document.addEventListener('yama-account-state',()=>{if(['#live-chat','#forum'].includes(location.hash))show(location.hash.slice(1));});
})();
